; ---------------------------------------------------------------
; void __near__ banked_call (unsigned char, __near__ __near__ function returning void *)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_banked_call: near

.segment	"CODE"

;
; void banked_call(unsigned char bankId, void (*method)(void)) {
;
	jsr     pushax
;
; bank_push(bankId);
;
	ldy     #$02
	lda     (sp),y
	jsr     _bank_push
;
; (*method)();
;
	ldy     #$01
	lda     (sp),y
	tax
	dey
	lda     (sp),y
	jsr     callax
;
; bank_pop();
;
	jsr     _bank_pop
;
; }
;
	jmp     incsp3

.endproc

; ---------------------------------------------------------------
; void __near__ bank_push (unsigned char)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_bank_push: near

.segment	"CODE"

;
; void bank_push(unsigned char bankId) {
;
	jsr     pusha
;
; bankBuffer[bankLevel] = get_prg_bank();
;
	lda     #<(_bankBuffer)
	ldx     #>(_bankBuffer)
	clc
	adc     _bankLevel
	bcc     L000B
	inx
L000B:	jsr     pushax
	jsr     _get_prg_bank
	ldy     #$00
	jsr     staspidx
;
; ++bankLevel;
;
	inc     _bankLevel
;
; set_prg_bank(bankId);
;
	ldy     #$00
	lda     (sp),y
	jsr     _set_prg_bank
;
; }
;
	jmp     incsp1

.endproc

; ---------------------------------------------------------------
; void __near__ bank_pop (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_bank_pop: near

.segment	"CODE"

;
; if (bankLevel != 0) {
;
	lda     _bankLevel
	beq     L0011
;
; --bankLevel;
;
	dec     _bankLevel
;
; set_prg_bank(bankBuffer[bankLevel]);
;
	ldy     _bankLevel
	lda     _bankBuffer,y
	jmp     _set_prg_bank
;
; }
;
L0011:	rts

.endproc

; ---------------------------------------------------------------
; void __near__ kill_player (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_kill_player: near

.segment	"CODE"

;
; game_mode = MODE_LEVEL_SELECT;
;
	lda     #$03
	sta     _game_mode
;
; scroll_x = 0;
;
	ldx     #$00
	txa
	sta     _scroll_x
	sta     _scroll_x+1
;
; set_scroll_x(0);
;
	jsr     _set_scroll_x
;
; load_level_select();
;
	jmp     _load_level_select

.endproc

; ---------------------------------------------------------------
; unsigned char __near__ bg_collision_sub (void)
; ---------------------------------------------------------------

.segment	"BANK0"

.proc	_bg_collision_sub: near

.segment	"BANK0"

;
; if (temp_y >= 0xf0)
;
	lda     _temp_y
	cmp     #$F0
	lda     _temp_y+1
	sbc     #$00
	bcc     L1359
;
; return 0;
;
	ldx     #$00
	txa
	rts
;
; coordinates = (temp_x >> 4) + (temp_y & 0xf0);
;
L1359:	lda     _temp_x
	ldx     _temp_x+1
	jsr     shrax4
	sta     ptr1
	lda     _temp_y
	and     #$F0
	clc
	adc     ptr1
	sta     _coordinates
;
; map = temp_room & 1; // high byte
;
	lda     _temp_room
	and     #$01
	sta     _map
;
; if (!map)
;
	lda     _map
	bne     L1362
;
; collision = c_map[coordinates];
;
	ldy     _coordinates
	lda     _c_map,y
;
; else
;
	jmp     LAF67
;
; collision = c_map2[coordinates];
;
L1362:	ldy     _coordinates
	lda     _c_map2,y
LAF67:	sta     _collision
;
; return c_metatile_map[collision];
;
	ldy     _collision
	ldx     #$00
	lda     _c_metatile_map,y
;
; }
;
	rts

.endproc

; ---------------------------------------------------------------
