.segment	"BANK0"

;
; collision_L = 0;
;
	lda     #$00
	sta     _collision_L
;
; collision_R = 0;
;
	sta     _collision_R
;
; collision_D = 0;
;
	sta     _collision_D
;
; if (Generic.y >= 0xf0)
;
	lda     _Generic+1
	cmp     #$F0
;
; return;
;
	bcc     LAF6B
;
; }
;
	rts
;
; location_with_scroll = Generic.x + scroll_x;
;
LAF6B:	lda     _Generic
	clc
	adc     _scroll_x
	pha
	lda     #$00
	adc     _scroll_x+1
	sta     _location_with_scroll+1
	pla
	sta     _location_with_scroll
;
; temp_x = location_with_scroll & 0xff;  // low byte x
;
	ldx     #$00
	sta     _temp_x
	stx     _temp_x+1
;
; temp_room = location_with_scroll >> 8; // high byte x
;
	lda     _location_with_scroll+1
	sta     _temp_room
;
; temp_y = Generic.y + 6; // y middle
;
	lda     _Generic+1
	clc
	adc     #$06
	bcc     L1381
	inx
L1381:	sta     _temp_y
	stx     _temp_y+1
;
; bg_collision_sub();
;
	jsr     _bg_collision_sub
;
; if (bg_collision_sub() & COL_ALL)
;
	jsr     _bg_collision_sub
	and     #$40
	beq     LAF69
;
; ++collision_L;
;
